-- #152 판정 등록과 별도 검토자 승인 (ADR-0093 decision 1 #173 items 1, 4, 5, 9 and 13, decision 3
-- the #152 rows; ADR-0103). Generated by `drizzle-kit generate`, then hand-edited where marked:
-- this header and the tail. The snapshot is as generated.
--
-- - market_judgements: every approved judgement of a market, v1 the first (only approved ones are
--   numbered; #176's corrections add the next): the result (VOID chosen here, #173 item 4), the
--   source picked from the rules — its priority with the name and address copied, all or none, none
--   only for a VOID — the fallback's reason (exactly for a fallback source) and the VOID's (exactly
--   for a VOID), the evidence links (1–5), what was confirmed (1–500) and the collection instant
--   (never after the publication), the rule version followed (ADR-0101 결과 5), the approver's
--   confirmation of the event deadline, the dispute window the approval read (1–10,080 minutes, the
--   release setting `market.dispute_window`), the publication instant and the 이의 기한 exactly
--   the one plus the other (#173 item 5), the approved `market_judgement` request (one judgement
--   each), the registrant, the approver (never the registrant) and the `provisional` event.
--   Permanent facts (N04 §5): no retention; buddha_app may INSERT and SELECT only, and a trigger
--   refuses an UPDATE or a DELETE whoever writes (below).
-- - markets.judgement_version: the current judgement, 1 or more; markets.dispute_deadline: its
--   deadline, mirrored for the worker's confirmation scan (the partial index on the PROVISIONAL
--   markets). Both null until a judgement is approved, and on every market judged by ADR-0046's
--   interim route before #152 (D4: no backfill, no 이의 기간 applied after the fact). The CHECK
--   markets_provisional_check holds that a PROVISIONAL market has both and its result: no market
--   has been PROVISIONAL before this migration (nothing took that edge), so it holds on every row.
CREATE TABLE "market_judgements" (
	"market_id" uuid NOT NULL,
	"version" integer NOT NULL,
	"result" "market_result" NOT NULL,
	"source_priority" smallint,
	"source_name" varchar(500),
	"source_url" varchar(500),
	"fallback_reason" text,
	"void_reason" text,
	"evidence_links" text[] NOT NULL,
	"evidence_description" text NOT NULL,
	"collected_at" timestamp (3) with time zone NOT NULL,
	"rule_version" integer,
	"event_deadline_confirmed" boolean NOT NULL,
	"dispute_window_minutes" integer NOT NULL,
	"published_at" timestamp (3) with time zone NOT NULL,
	"dispute_deadline" timestamp (3) with time zone NOT NULL,
	"approval_id" uuid NOT NULL,
	"registered_by" text NOT NULL,
	"approved_by" text NOT NULL,
	"provisional_event_id" bigint NOT NULL,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "market_judgements_market_id_version_pk" PRIMARY KEY("market_id","version"),
	CONSTRAINT "market_judgements_approval_id_unique" UNIQUE("approval_id"),
	CONSTRAINT "market_judgements_version_check" CHECK ("market_judgements"."version" >= 1 AND "market_judgements"."rule_version" >= 1),
	CONSTRAINT "market_judgements_source_check" CHECK (("market_judgements"."source_priority" IS NULL) = ("market_judgements"."source_name" IS NULL) AND ("market_judgements"."source_priority" IS NULL) = ("market_judgements"."source_url" IS NULL) AND "market_judgements"."source_priority" BETWEEN 0 AND 3 AND ("market_judgements"."source_priority" IS NOT NULL OR "market_judgements"."result" = 'VOID')),
	CONSTRAINT "market_judgements_fallback_reason_check" CHECK (("market_judgements"."fallback_reason" IS NOT NULL) = (coalesce("market_judgements"."source_priority", 0) >= 1) AND ("market_judgements"."fallback_reason" IS NULL OR (btrim("market_judgements"."fallback_reason") <> '' AND char_length("market_judgements"."fallback_reason") <= 500))),
	CONSTRAINT "market_judgements_void_reason_check" CHECK (("market_judgements"."void_reason" IS NOT NULL) = ("market_judgements"."result" = 'VOID') AND ("market_judgements"."void_reason" IS NULL OR (btrim("market_judgements"."void_reason") <> '' AND char_length("market_judgements"."void_reason") <= 500))),
	CONSTRAINT "market_judgements_evidence_check" CHECK (array_ndims("market_judgements"."evidence_links") = 1 AND cardinality("market_judgements"."evidence_links") BETWEEN 1 AND 5 AND array_position("market_judgements"."evidence_links", NULL) IS NULL AND btrim("market_judgements"."evidence_description") <> '' AND char_length("market_judgements"."evidence_description") <= 500 AND "market_judgements"."collected_at" <= "market_judgements"."published_at"),
	CONSTRAINT "market_judgements_dispute_check" CHECK ("market_judgements"."dispute_window_minutes" BETWEEN 1 AND 10080 AND "market_judgements"."dispute_deadline" = "market_judgements"."published_at" + make_interval(mins => "market_judgements"."dispute_window_minutes")),
	CONSTRAINT "market_judgements_approver_check" CHECK ("market_judgements"."approved_by" <> "market_judgements"."registered_by")
);
--> statement-breakpoint
ALTER TABLE "markets" ADD COLUMN "judgement_version" integer;--> statement-breakpoint
ALTER TABLE "markets" ADD COLUMN "dispute_deadline" timestamp (3) with time zone;--> statement-breakpoint
ALTER TABLE "market_judgements" ADD CONSTRAINT "market_judgements_market_id_markets_id_fk" FOREIGN KEY ("market_id") REFERENCES "public"."markets"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
