ALTER TABLE "market_judgements" ADD CONSTRAINT "market_judgements_registered_by_user_id_fk" FOREIGN KEY ("registered_by") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_judgements" ADD CONSTRAINT "market_judgements_approved_by_user_id_fk" FOREIGN KEY ("approved_by") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "market_judgements" ADD CONSTRAINT "market_judgements_provisional_event_id_market_events_id_fk" FOREIGN KEY ("provisional_event_id") REFERENCES "public"."market_events"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
