ALTER TABLE "markets" ADD CONSTRAINT "markets_judgement_version_check" CHECK ("markets"."judgement_version" >= 1);--> statement-breakpoint
ALTER TABLE "markets" ADD CONSTRAINT "markets_provisional_check" CHECK ("markets"."status" <> 'provisional' OR ("markets"."judgement_version" IS NOT NULL AND "markets"."dispute_deadline" IS NOT NULL AND "markets"."resolved_result" IS NOT NULL));--> statement-breakpoint
-- Hand-edited: a judgement is a permanent fact (N04 §5), never rewritten or removed. buddha_app
-- keeps SELECT/INSERT of the default privileges in docker/postgres/init/01-roles.sql and loses
-- UPDATE and DELETE.
REVOKE UPDATE, DELETE ON TABLE "market_judgements" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: nor does any other role (the migration role, a script): the deadline is fixed when
-- the provisional result is published (#173 item 5), the public judging record shows what was
-- judged and on what evidence (#173 item 13, #24) and a correction is a new version (#176), so a
-- judgement stays as it was approved, whoever writes. TRUNCATE fires no row trigger: the wipe
-- (wipe.ts) still empties the table.
CREATE FUNCTION market_judgements_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'judgement % of market % is a permanent record and takes no %', OLD.version,
    OLD.market_id, TG_OP
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;--> statement-breakpoint
CREATE TRIGGER market_judgements_keep_record
  BEFORE UPDATE OR DELETE ON "market_judgements"
  FOR EACH ROW EXECUTE FUNCTION market_judgements_keep_record();
